using System.Collections.Generic;

namespace TAOM.Features.TroopProgression;

// Volunteer recruitment pool for Cardolan, the southern of Arnor's three kingdoms (#978; troops
// generated by tools/generate_cardolan_troops.py). The data half of VolunteerRecruitmentService,
// registered by the static ctor in the core file. Lookup priority: conditional > settlement > clan >
// culture (troops.md).
public partial class VolunteerRecruitmentService
{
    private static void InitializeCardolanCulture()
    {
        // Two roots reach the whole tree: the Levy heads the spear line, and the Dunadan of Cardolan
        // splits into the knights and the Minhiriath bowmen. Levy-heavy, as Arthedain's.
        CultureMap["cardolan"] = new List<VolunteerChance>
        {
            new VolunteerChance("cardolan_levy", 6),
            new VolunteerChance("cardolan_dunadan", 2)
        };
    }
}
